import { useEffect, useState } from 'react'
import { GearData, GearNode } from '../type/gear'

// Collections generated by scripts/generate-gear.mjs
export const GEAR_COLLECTION_IDS = [5, 6]

const WIKI_URL = 'https://terraria.wiki.gg/wiki'

// @ts-ignore
const GEAR_VERSION = __GEAR_VERSION__

export const wikiLink = (name: string): string =>
  `${WIKI_URL}/${encodeURIComponent(name.replace(/ /g, '_'))}`

export const hasDetails = (node: GearNode | undefined): boolean =>
  !!node && !!(node.info || node.anyOf || node.recipes || node.shimmer || node.drops)

// The gear data is large, so it is only fetched when a gear page is opened
let gearRequest: Promise<GearData> | null = null

export function useGearData(): { data: GearData | null; failed: boolean } {
  const [data, setData] = useState<GearData | null>(null)
  const [failed, setFailed] = useState<boolean>(false)

  useEffect(() => {
    let active = true
    if (!gearRequest) {
      gearRequest = fetch(`data/gear.json?v=${GEAR_VERSION}`).then((response) => {
        if (!response.ok) throw new Error(`HTTP ${response.status}`)
        return response.json()
      })
    }
    gearRequest
      .then((json) => active && setData(json))
      .catch(() => {
        gearRequest = null
        if (active) setFailed(true)
      })
    return (): void => {
      active = false
    }
  }, [])

  return { data, failed }
}
